import{d as c,C as t,o as p,c as u,j as a,a as r,E as n,a3 as b}from"./chunks/framework.Q4yG9rk_.js";const _=JSON.parse('{"title":"道德经第九章","description":"从持盈、揣锐与富贵而骄，读到功成身退的分寸。","frontmatter":{"title":"道德经第九章","description":"从持盈、揣锐与富贵而骄，读到功成身退的分寸。","category":"guide","aliases":["道德经第九章","老子第九章","dao de jing chapter 9"],"source":["王弼《道德真经注》卷一"]},"headers":[],"relativePath":"daoism/dao-de-jing/chapter-09.md","filePath":"daoism/dao-de-jing/chapter-09.md","lastUpdated":1794189804000}'),m={name:"daoism/dao-de-jing/chapter-09.md"},y=c({...m,setup(g){const i=[{id:"fullness-and-sharpness",label:"持而盈之，不如其已",showLabel:!0,sentences:[["持而",{text:"盈",glossary:"ying"},"之，不如其",{text:"已",glossary:"yi"},"；"],[{text:"揣",glossary:"zhui"},"而锐之，不可长保。"]],note:["【白话】把持着还要使它充满，不如适时停止；反复捶治，使锋端更加尖利，不能长久保持。","【王弼注择要】「持谓不失德也。」王弼以持守已有之德解释持，并指出在此基础上又求盈满，便有倾危；对揣锐则说「既揣末令尖，又锐之令利」。","【读法】持盈可以借满器帮助理解，但王弼并不只讲拿着一只杯子。揣在这里取捶治义，本页读 zhuī，不按揣测来译；重点在不断加满、加锐带来的不稳。"]},{id:"wealth-and-pride",label:"金玉满堂，莫之能守",showLabel:!0,sentences:[["金玉满堂，莫之能守；"],["富贵而骄，自",{text:"遗",glossary:"yi-leave"},"其",{text:"咎",glossary:"jiu"},"。"]],note:["【白话】金玉堆满屋堂，没有谁能永远守住；富贵以后骄傲自大，就是给自己留下祸患。","【读法】前句反省积聚到满仍难长守，后句进一步指出骄的后果。不是只要拥有财富就自动有罪，也不是把一切损失都归咎于当事人；文本针对的是满而求守、贵而生骄。"]},{id:"withdrawing-after-completion",label:"功成身退，天之道",showLabel:!0,sentences:[["功成",{text:"身退",glossary:"shentui"},"，天之道。"]],note:["【白话】事情成就之后，退离对功位的占居，这是合于天道的方式。","【王弼注择要】「四时更运，功成则移。」王弼用四季轮替说明，完成一时的作用，便随时序转移，不永远占住同一个位置。","【读法】身退与前文的盈、锐、满、骄形成收束。它不是未尽责任就抽身，也不必一概落实为辞职隐居；先分辨事情是否已成，以及怎样妥善交接。"]}],o=[{id:"ying",term:"盈",sense:1},{id:"yi",term:"已",sense:1},{id:"zhui",term:"揣",sense:1,pinyin:"zhuī"},{id:"yi-leave",term:"遗",sense:1,pinyin:"yí"},{id:"jiu",term:"咎",sense:1,context:"富贵而骄为自己留下的祸患，与易经断辞语境有别，字义相通。"},{id:"shentui",term:"身退",sense:1}];return(x,e)=>{const s=t("DaoReadingPrelude"),l=t("DaoTextReading"),d=t("DaoLineGuide"),h=t("DaoKeywordCards");return p(),u("div",null,[e[0]||(e[0]=a("h1",{id:"道德经第九章",tabindex:"-1"},[r("道德经第九章 "),a("a",{class:"header-anchor",href:"#道德经第九章","aria-label":'Permalink to "道德经第九章"'},"​")],-1)),n(s,{title:"什么时候该停，怎样完成后离开",summary:"本章连用盈、锐、满、骄，指出事情向过度推进时的危险，最后以四时般的功成身退收束。先辨认真正的问题，再谈停与退，才不至于把它读成对努力或成就的否定。",points:[{label:"先读",text:"四个事例分别在哪里超过了分寸？"},{label:"再辨",text:"持守已有与继续求满有什么不同？"},{label:"后想",text:"功成之后，怎样判断何时应当转移？"}],hint:"竹简模式先通读；经典阅读可展开段释义、点击标记字词查义。"}),e[1]||(e[1]=a("h2",{id:"【原典层】原文与段级释义",tabindex:"-1"},[r("【原典层】原文与段级释义 "),a("a",{class:"header-anchor",href:"#【原典层】原文与段级释义","aria-label":'Permalink to "【原典层】原文与段级释义"'},"​")],-1)),n(l,{sections:i,glossary:o,tone:"ink",density:"comfortable","aria-label":"《道德经》第九章原文"}),e[2]||(e[2]=a("h2",{id:"【导读层】核心句引读",tabindex:"-1"},[r("【导读层】核心句引读 "),a("a",{class:"header-anchor",href:"#【导读层】核心句引读","aria-label":'Permalink to "【导读层】核心句引读"'},"​")],-1)),n(d,{lines:[{text:"持而盈之，不如其已；揣而锐之，不可长保。",tone:"设限",guide:"持守不是无限加满，锋利也不是越尖越好。两句把注意力引向超过限度之后的脆弱。"},{text:"富贵而骄，自遗其咎。",tone:"转人",guide:"从满与锐转到人的骄，前面的物象由此落到处世。得到一些东西之后怎样对待它，比单看拥有多少更关键。"},{text:"功成身退，天之道。",tone:"知时",guide:"王弼以四时更运说明退，着眼于时序中位置与作用的转移。完成、交接与转身可以相连，不必把退缩成突然离场。"}]}),e[3]||(e[3]=a("h2",{id:"【注释层】字词释义",tabindex:"-1"},[r("【注释层】字词释义 "),a("a",{class:"header-anchor",href:"#【注释层】字词释义","aria-label":'Permalink to "【注释层】字词释义"'},"​")],-1)),n(h,{items:o}),e[4]||(e[4]=b('<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-盈、锐、满、骄怎样连成一章" tabindex="-1">象：盈、锐、满、骄怎样连成一章？ <a class="header-anchor" href="#象-盈、锐、满、骄怎样连成一章" aria-label="Permalink to &quot;象：盈、锐、满、骄怎样连成一章？&quot;">​</a></h3><p>盈与满都涉及容受的限度，锐涉及锋端难以长保，骄则把积累转成自我膨胀。几个例子并非论证所有增加都有害，而是让读者看见：只盯着更多、更尖、更高，可能同时削弱保持它们的条件。</p><h3 id="理-为什么结尾以天道说明「退」" tabindex="-1">理：为什么结尾以天道说明「退」？ <a class="header-anchor" href="#理-为什么结尾以天道说明「退」" aria-label="Permalink to &quot;理：为什么结尾以天道说明「退」？&quot;">​</a></h3><p>王弼把天道落实到四季各有其时、功成则移。一季尽其作用后，不继续占据全年；人的成就也可放在变化的时序中理解。这个譬喻强调完成之后仍有转移，不能据此预言某个具体人的盛衰。</p><h3 id="用-怎样区别知止与半途而废" tabindex="-1">用：怎样区别知止与半途而废？ <a class="header-anchor" href="#用-怎样区别知止与半途而废" aria-label="Permalink to &quot;用：怎样区别知止与半途而废？&quot;">​</a></h3><p>先说清目标、责任与完成条件。事情尚有未交付的部分，不能只借身退摆脱承担；任务已经完成，也不必靠不断扩张来证明自己的价值。是否需要继续、维护或交接，应根据事实与共同约定判断。</p><h2 id="【解读层】现代解读与启发" tabindex="-1">【解读层】现代解读与启发 <a class="header-anchor" href="#【解读层】现代解读与启发" aria-label="Permalink to &quot;【解读层】现代解读与启发&quot;">​</a></h2><p><strong>在开始时说明完成的标准。</strong> 做项目或学习专题，可以先约定什么算够用、哪些结果必须交付。达到目标后复盘，再决定是否增加范围，能减少无止境加码造成的消耗。</p><p><strong>把交接当作完成的一部分。</strong> 留下资料、说明风险、交还权限，让后来者能继续，常比长期占着每一个决定更有益。适时退出某个角色，也可以是对成果的负责，而非否定已有投入。</p><h2 id="【个人记录】我的笔记" tabindex="-1">【个人记录】我的笔记 <a class="header-anchor" href="#【个人记录】我的笔记" aria-label="Permalink to &quot;【个人记录】我的笔记&quot;">​</a></h2><p>留给自己的续读问题：我正在继续增加的一件事，还服务于原来的目标吗？若已经完成，怎样交接才能让成果继续发挥作用？</p><h2 id="校读说明与参考来源" tabindex="-1">校读说明与参考来源 <a class="header-anchor" href="#校读说明与参考来源" aria-label="Permalink to &quot;校读说明与参考来源&quot;">​</a></h2><ul><li>「功成身退」保留本站通行文字；HFL 电子录文作「功遂身退」，王弼注仍以「功成则移」解释。</li><li>「揣」依捶治、使尖之义解释，本页读 zhuī；字音另参<a href="https://www.zdic.net/hans/%E6%8F%A3" target="_blank" rel="noreferrer">汉典「揣」条</a>。异读不据此混作揣测。</li><li>「咎」在这里指祸患；身退的现代引申以完成责任和妥善交接为前提。</li></ul><p>参考：<a href="https://github.com/kanripo/KR5c0073/blob/b988441bd55861741c850e1dff4a2d4f895daf3d/KR5c0073_001.txt" target="_blank" rel="noreferrer">王弼《道德真经注》卷一 HFL 本电子录文，005b–006a</a>。</p>',15))])}}});export{_ as __pageData,y as default};
